 internal const string StartPage="""
<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>Новая вкладка · NORA</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#202020;color:#eeeee6;font:15px/1.7 'Segoe UI',Arial,sans-serif}main{max-width:760px;margin:12vh auto;padding:40px}small{font-size:10px;letter-spacing:2px;color:#909083}h1{font-size:42px;font-weight:500;letter-spacing:-1.4px;line-height:1.2;margin:30px 0 18px}p{color:#aaa998}.links{display:flex;gap:10px;margin:32px 0}a{padding:18px 24px;border:1px solid #49493c;border-radius:16px;text-decoration:none;color:#ddddca;background:#2b2b25;flex:1;font-size:13px}a:hover{border-color:#989883}a:focus-visible{outline:2px solid #e2e2c8;outline-offset:4px}.note{border-top:1px solid #3c3c30;padding-top:20px;font-size:12px;color:#8d8d79}</style></head><body><main><small>NORA / BROWSER</small><h1>Новая вкладка.<br>Новые возможности.</h1><p>Введи адрес или поисковый запрос в строке сверху.</p><div class="links"><a href="https://www.google.com/">Google ↗</a><a href="https://github.com/">GitHub ↗</a><a href="https://web.telegram.org/k/">Telegram ↗</a></div><p class="note">Эта стартовая страница работает офлайн. Вход выполняется на сайте. Пароли, коды и платёжные данные не отправляй в чат.</p></main></body></html>
""";
 static string StartPageFor(string lang){string html=StartPage;if(lang=="en")return html.Replace("Новая вкладка.","New tab.").Replace("Новые возможности.","New possibilities.").Replace("Введи адрес или поисковый запрос в строке сверху.","Enter a website address or search query above.").Replace("Эта стартовая страница работает офлайн. Вход выполняется на сайте. Пароли, коды и платёжные данные не отправляй в чат.","This start page works offline. Sign in on the website. Do not send passwords, codes, or payment details in chat.");if(lang=="zh-CN")return html.Replace("Новая вкладка.","新标签页。").Replace("Новые возможности.","新的可能。").Replace("Введи адрес или поисковый запрос в строке сверху.","在上方输入网址或搜索内容。").Replace("Эта стартовая страница работает офлайн. Вход выполняется на сайте. Пароли, коды и платёжные данные не отправляй в чат.","此起始页可离线使用。请在网站上登录。不要在聊天中发送密码、验证码或付款信息。");return html;}
 public static string SearchUrl(string query)=>"https://www.google.com/search?q="+Uri.EscapeDataString(query[..Math.Min(query.Length,1000)]);
