 public async Task Init(){try{await(initialization??=Initialize());}catch{initialization=null;throw;}}
 async Task Initialize(){environment=await CoreWebView2Environment.CreateAsync(null,profile);await NewTab();}
 async Task<WebView2> NewTab(){
  if(views.Count>=8)throw new Exception("Не более 8 вкладок. Закрой ненужную вкладку.");
  var web=new WebView2{Dock=DockStyle.Fill};pages.Controls.Add(web);views.Add(web);
  try{await web.EnsureCoreWebView2Async(environment);var core=web.CoreWebView2;core.Profile.IsPasswordAutosaveEnabled=false;core.Profile.IsGeneralAutofillEnabled=false;core.Settings.AreHostObjectsAllowed=false;core.Settings.AreDevToolsEnabled=false;core.Settings.IsWebMessageEnabled=true;
   core.WebMessageReceived+=(_,e)=>{try{if(e.TryGetWebMessageAsString()=="nora-human-activity")HumanActivity?.Invoke();}catch{}};
   // All frames report only trusted activity, never the text entered or any control values.
   await core.AddScriptToExecuteOnDocumentCreatedAsync("(()=>{let last=0;for(const name of ['pointerdown','pointermove','keydown','wheel','input','touchstart'])addEventListener(name,e=>{if(!e.isTrusted)return;const now=Date.now();if(now-last<150)return;last=now;chrome.webview.postMessage('nora-human-activity')},{capture:true,passive:true})})()");
   core.PermissionRequested+=(_,e)=>e.State=CoreWebView2PermissionState.Deny;
   core.NewWindowRequested+=async(_,e)=>{e.Handled=true;var def=e.GetDeferral();string url=e.Uri;try{await Validate(url);var target=await NewTab();target.CoreWebView2.Navigate(url);}catch(Exception ex){status.Text=ex.Message;}finally{def.Complete();}};
   core.DownloadStarting+=async(_,e)=>{var def=e.GetDeferral();e.Cancel=true;try{await Validate(e.DownloadOperation.Uri);HumanActivity?.Invoke();using var dialog=new SaveFileDialog{Title="Скачать файл из браузера · не запускается автоматически",FileName=SafeDownloadName(e.ResultFilePath),Filter="Файл|*.*",OverwritePrompt=true};if(dialog.ShowDialog(this)==DialogResult.OK){e.ResultFilePath=dialog.FileName;e.Handled=true;e.Cancel=false;status.Text="Скачивание разрешено. NORA не запускает загруженные файлы.";}}catch(Exception ex){status.Text="Скачивание отменено: "+ex.Message;}finally{def.Complete();}};
   core.NavigationStarting+=(_,e)=>{if(e.Uri=="about:blank")return;try{BrowserNetworkPolicy.PublicAddress(e.Uri);}catch{e.Cancel=true;status.Text="Только публичный HTTPS; локальные файлы запрещены.";}};
   core.AddWebResourceRequestedFilter("*",CoreWebView2WebResourceContext.All);core.WebResourceRequested+=async(_,e)=>{if(e.Request.Uri.StartsWith("data:")||e.Request.Uri.StartsWith("blob:")||e.Request.Uri=="about:blank")return;var def=e.GetDeferral();try{await Validate(e.Request.Uri);}catch{e.Response=core.Environment.CreateWebResourceResponse(new MemoryStream(),403,"Blocked","");}finally{def.Complete();}};
   core.SourceChanged+=(_,_)=>{if(active==web)address.Text=core.Source;PageChanged?.Invoke();};core.DocumentTitleChanged+=(_,_)=>{RenderTabs();PageChanged?.Invoke();};
   Activate(web);core.NavigateToString(StartPageFor(language));return web;
  }catch{views.Remove(web);web.Dispose();throw;}
 }
 static string SafeDownloadName(string path){string name=Path.GetFileName(path);foreach(char c in Path.GetInvalidFileNameChars())name=name.Replace(c,'_');return string.IsNullOrWhiteSpace(name)?"download.bin":name;}
 void Activate(WebView2 web){active=web;foreach(var v in views)v.Visible=v==web;web.BringToFront();address.Text=CurrentUrl=="about:blank"?"":CurrentUrl;RenderTabs();PageChanged?.Invoke();}
 void RenderTabs(){foreach(Control c in tabs.Controls.Cast<Control>().ToArray())c.Dispose();foreach(var web in views){var item=new Panel{Width=192,Height=40,BackColor=web==active?Color.FromArgb(55,55,55):Color.FromArgb(32,32,32),Margin=new(2,0,2,0)};var label=new RoundedButton{Dock=DockStyle.Fill,Text=string.IsNullOrWhiteSpace(web.CoreWebView2?.DocumentTitle)?"Новая вкладка":web.CoreWebView2.DocumentTitle,FlatStyle=FlatStyle.Flat,ForeColor=Color.Gainsboro};var x=new RoundedButton{Dock=DockStyle.Right,Width=36,Text="×",AccessibleName="Закрыть вкладку",FlatStyle=FlatStyle.Flat,ForeColor=Color.Gray};label.Click+=(_,_)=>{HumanActivity?.Invoke();Activate(web);};x.Click+=async(_,_)=>{try{HumanActivity?.Invoke();bool was=active==web;views.Remove(web);web.Dispose();if(was)active=null;if(views.Count==0)await NewTab();else if(was)Activate(views[^1]);else RenderTabs();}catch(Exception ex){status.Text="Не удалось открыть вкладку: "+ex.Message;}};item.Controls.Add(label);item.Controls.Add(x);tabs.Controls.Add(item);}var add=new RoundedButton{Text="+",AccessibleName="Новая вкладка",Width=44,Height=40,FlatStyle=FlatStyle.Flat,ForeColor=Color.Gainsboro};add.Click+=async(_,_)=>{HumanActivity?.Invoke();try{await NewTab();address.Focus();}catch(Exception e){status.Text=e.Message;}};tabs.Controls.Add(add);}
 public string TabSummary()=>string.Join("\n",views.Select((v,i)=>$"{i+1}. {(v==active?"[активна] ":"")}{v.CoreWebView2?.DocumentTitle} — {v.CoreWebView2?.Source}"));
 public async Task NavigateTool(string action,int index,CancellationToken ct){await Init();ct.ThrowIfCancellationRequested();if(action=="browser_tab"){if(index<1||index>views.Count)throw new Exception("Нет вкладки с таким index; вызови browser_tabs");Activate(views[index-1]);return;}var core=active!.CoreWebView2;if(action=="browser_back"&&!core.CanGoBack)throw new Exception("Нет предыдущей страницы");if(action=="browser_forward"&&!core.CanGoForward)throw new Exception("Нет следующей страницы");var done=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);void End(object? s,CoreWebView2NavigationCompletedEventArgs e)=>done.TrySetResult(e.IsSuccess);core.NavigationCompleted+=End;try{if(action=="browser_back")core.GoBack();else if(action=="browser_forward")core.GoForward();else if(action=="browser_reload")core.Reload();else throw new Exception("Неизвестное действие");if(!await done.Task.WaitAsync(TimeSpan.FromSeconds(40),ct))throw new Exception("Переход не завершился успешно");}finally{core.NavigationCompleted-=End;}}
 public async Task ResetTabs(){await Init();foreach(var web in views.ToArray())web.Dispose();views.Clear();active=null;await NewTab();}
 public async Task Navigate(string url,CancellationToken ct){await Init();address.Text=url=="about:blank"?"":url;if(url!="about:blank")await Validate(url);ct.ThrowIfCancellationRequested();var core=active!.CoreWebView2;var done=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);string navigationError="неизвестная ошибка";ulong? navigationId=null;void Started(object? _,CoreWebView2NavigationStartingEventArgs e){navigationId??=e.NavigationId;}void Completed(object? _,CoreWebView2NavigationCompletedEventArgs e){if(navigationId!=null&&e.NavigationId!=navigationId)return;navigationError=e.WebErrorStatus.ToString();done.TrySetResult(e.IsSuccess);}core.NavigationStarting+=Started;core.NavigationCompleted+=Completed;try{status.Text="Загрузка…";if(url=="about:blank")core.NavigateToString(StartPageFor(language));else core.Navigate(url);using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(40));using var stop=timeout.Token.Register(()=>{try{BeginInvoke(()=>core.Stop());}catch{}});bool ok=await done.Task.WaitAsync(timeout.Token);if(!ok)throw new Exception("Страница не загрузилась: "+navigationError+". Проверь сеть, DNS и HTTPS-адрес.");await Task.Delay(300,ct);status.Text=L("Браузер доступен пользователю и NORA одновременно. Пароли и коды вводи вручную.","The browser is shared with NORA. Enter passwords and codes manually.","浏览器由用户和 NORA 共用。密码和验证码请手动输入。");}catch(OperationCanceledException)when(!ct.IsCancellationRequested){throw new TimeoutException("Страница не загрузилась за 40 секунд. Попробуй ещё раз или проверь интернет.");}finally{core.NavigationStarting-=Started;core.NavigationCompleted-=Completed;}}
 public async Task<BrowserPage> Read(CancellationToken ct){await Init();ct.ThrowIfCancellationRequested();if(CurrentUrl!="about:blank")await Validate(CurrentUrl);using var stream=typeof(BrowserWindow).Assembly.GetManifestResourceStream("LocalChat.browser-read.js")??throw new Exception("Модуль чтения страницы не найден");using var reader=new StreamReader(stream);string script=await reader.ReadToEndAsync(ct);var result=await active!.CoreWebView2.ExecuteScriptAsync(script);ct.ThrowIfCancellationRequested();return JsonSerializer.Deserialize<BrowserPage>(result,Disk.Json)??throw new Exception("Нет читаемого содержимого.");}
 public async Task<byte[]> CapturePage(CancellationToken ct){await Init();ct.ThrowIfCancellationRequested();if(CurrentUrl!="about:blank")await Validate(CurrentUrl);using var bytes=new MemoryStream();await active!.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,bytes);return bytes.ToArray();}
